sp_widget.client_script:
api.controller = function() {
    var c = this;
    if (c.data.redirectPage) {
        window.location.href = '?id=' + c.data.redirectPage;
    }
};

sp_widget.script:
(function() {
    data.redirectPage = '';
    data.accessDenied = false;
    data.userName = gs.getUserDisplayName() || 'User';

    if (gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin')) {
        data.redirectPage = 'x_1956908_wareho_0_sup_dashboard';
    } else if (gs.hasRole('x_1956908_wareho_0.technician')) {
        data.redirectPage = 'x_1956908_wareho_0_tech_dashboard';
    } else if (gs.hasRole('x_1956908_wareho_0.staff')) {
        data.redirectPage = 'x_1956908_wareho_0_staff_dashboard';
    } else if (gs.isLoggedIn()) {
        data.redirectPage = 'x_1956908_wareho_0_staff_dashboard';
    } else {
        data.redirectPage = 'wei_landing';
    }
})();
